import java.io.PrintWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<String> notas = new ArrayList<>();
        notas.add("Revisar examen de matematicas");
        notas.add("Entregar proyecto de programacion");
        notas.add("Estudiar para final de historia");
        notas.add("Comprar material de laboratorio");

        try (PrintWriter pw = new PrintWriter(new FileWriter("notas.txt"))) {
            for (String nota : notas) {
                pw.println(nota);
            }
            System.out.println("Saved " + notas.size() + " notes to notas.txt");
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

